func ProofFor(caseID string) (meta.Proof, bool) {
	raw, ok := proofJSON[caseID]
	if !ok {
		return meta.Proof{}, false
	}
	var proof meta.Proof
	if err := json.Unmarshal([]byte(raw), &proof); err != nil {
		return meta.Proof{}, false
	}
	return proof, true
}

func Execute(caseID string, input meta.FixtureInput) (meta.ExecutionResult, error) {
	proof, ok := ProofFor(caseID)
	if !ok {
		return meta.ExecutionResult{}, fmt.Errorf("unknown generated proof %q", caseID)
	}
	return meta.ExecuteProof(proof, input)
}
